edits.newText:
.kpi-figure {
  font-size: 2.1rem;
  font-weight: 700;
  color: var(--text-white);
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.kpi-unit {
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-left: 2px;
}

