edits.oldText:
.kpi-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 12px;
  padding: 24px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 130px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
}

.kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 12px;
  right: 12px;
  height: 2px;
  background: #25334d;
  border-radius: 2px;
}

.kpi-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.kpi-stat-wrapper {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 14px;
  gap: 12px;
}

.kpi-figure {
  font-size: 2.1rem;
  font-weight: 700;
  color: var(--text-white);
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.kpi-unit {
  font-size: 1.25rem;
  font-weight: 500;
  color: var(--text-muted);
  margin-left: 2px;
}

